import sys

def find_dominant_piranha(t, cases):
    results = []
    for n, a in cases:
        left = [0] * n
        right = [0] * n

        for i in range(1, n):
            if a[i] > a[i - 1]:
                left[i] = left[i - 1] + 1

        for i in range(n - 2, -1, -1):
            if a[i] > a[i + 1]:
                right[i] = right[i + 1] + 1

        for i in range(n):
            if left[i] + right[i] >= n - 1:
                results.append(i + 1)
                break
        else:
            results.append(-1)

    return results

